// Package contractsentinel charvalidate: character-level legality checks for
// user-supplied audit submissions, performed before any JSON decoding.
//
// encoding/json silently rewrites two kinds of bad input into the replacement
// character U+FFFD instead of rejecting it:
//
//   - bytes that are not valid UTF-8, anywhere in the document;
//   - Unicode escapes (\uXXXX) inside JSON strings that do not form a legal
//     surrogate pair: a lone high surrogate, a lone low surrogate, or a high
//     surrogate followed by something other than a low surrogate (a reversed
//     pair included).
//
// For an audit submission that silently changes the evidence text of a
// 发现缺陷 record, and changes the very content that feeds the artifact hash
// when it appears in the source. A successful report must never be built from
// rewritten content, so the whole submission is rejected at the character
// level first.
//
// Legal content stays legal: a directly written U+FFFD is an ordinary
// character, and the literal text "\uD800" (an escaped backslash followed by
// uD800) is ordinary text — neither is a surrogate problem.
package contractsentinel

import (
	"fmt"
	"unicode/utf8"
)

// charError locates one character-legality problem. Positions are 1-based
// (line, column) with an additional 0-based byte offset; columns count runes,
// so a multi-byte character occupies one column.
type charError struct {
	problem string // "invalid UTF-8 encoding" or "invalid Unicode escape in JSON string"
	line    int
	column  int
	offset  int
	detail  string
}

func (e *charError) Error() string {
	return fmt.Sprintf("%s at line %d, column %d (byte offset %d): %s",
		e.problem, e.line, e.column, e.offset, e.detail)
}

// validateJSONCharacters scans data as JSON text and rejects the first
// character-legality violation: an illegal UTF-8 byte anywhere, or an
// unpaired / misordered surrogate escape within any JSON string (member names
// included — strings are strings, whether they carry a fixed field, a value,
// or nested extension data). It performs no JSON syntax validation: malformed
// JSON is left to the decoder that runs next, and never produces a false
// character error on a document that was valid JSON.
func validateJSONCharacters(data []byte) error {
	i, n := 0, len(data)
	line, column := 1, 1

	// Position captured when a high surrogate is seen, so the lone surrogate is
	// reported where it was written rather than where pairing failed.
	type surrogatePos struct {
		value  rune
		line   int
		column int
		offset int
	}

	inString := false
	var pending surrogatePos
	hasPending := false

	for i < n {
		c := data[i]

		// Non-ASCII bytes: validate UTF-8 both inside and outside strings.
		// A genuinely encoded U+FFFD decodes as U+FFFD over three bytes and is
