				return true
			}
			i += sz
			continue
		}
		if !str {
			if c == '"' {
				str = true
			}
			i++
			continue
		}
		if c == '"' {
			if pendingHigh {
				return true
			}
			str = false
			i++
			continue
		}
		if c == '\\' && i+5 < n && data[i+1] == 'u' {
			var v rune
			ok := true
