				ch := data[i+2+k]
				var d rune
				switch {
				case ch >= '0' && ch <= '9':
					d = rune(ch - '0')
				case ch >= 'a' && ch <= 'f':
					d = rune(ch-'a') + 10
				case ch >= 'A' && ch <= 'F':
					d = rune(ch-'A') + 10
				default:
					ok = false
				}
				v = v<<4 | d
			}
			if ok {
				switch {
				case v >= 0xD800 && v <= 0xDBFF:
					if pendingHigh {
						return true
					}
					pendingHigh = true
				case v >= 0xDC00 && v <= 0xDFFF:
