			b = append(b, []byte(key)...)
			b = append(b, ':')
			v := atoms[r.Intn(len(atoms))]
			b = append(b, []byte(v)...)
			if r.Intn(3) == 0 {
				b = append(b, 0x20)
			}
			if e < elems-1 {
				b = append(b, ',')
			}
		}
		b = append(b, '}')
		_ = depth
		if r.Intn(6) == 0 && len(b) > 2 {
			pos := r.Intn(len(b))
			b = append(b[:pos], append([]byte{badByte[r.Intn(len(badByte))]}, b[pos:]...)...)
		}
		got := validateJSONCharacters(b)
		want := referenceBad(b)
