		// no false positives there); invalid JSON may go either way.
		var tmp any
		wellFormed := json.Unmarshal(b, &tmp) == nil
		if wellFormed {
			if (got != nil) != want {
				t.Fatalf("mismatch on well-formed JSON:\n bytes=% x\n got=%v wantBad=%v", b, got, want)
			}
			// Stronger: every well-formed doc the reference flags must actually
			// be one json decodes with replacement (proves it is a real case).
		}
	}
	fmt.Println("differential fuzz done")
}

