	atoms := []string{
		`"abc"`, `"中文"`, `"aAb"`, `"😀"`, `"😀"`,
		`"\uD800"`, `"\uDC00"`, `"\uD800\uD800"`, `"\uDC00\uD800"`,
		`"\\"`, `"\\uD800"`, `"line\n"`, `"  "`, `"�"`, `123`, `true`, `null`,
		`{"k":"v"}`, `["x","y"]`,
	}
	badByte := []byte{0xFF, 0xC0, 0xFE, 0x80, 0xE2, 0xF0}
	for iter := 0; iter < 200000; iter++ {
