		depth := 0
		elems := r.Intn(4)
		b = append(b, '{')
		for e := 0; e < elems; e++ {
			key := atoms[r.Intn(len(atoms))]
			b = append(b, []byte(key)...)
			b = append(b, ':')
			v := atoms[r.Intn(len(atoms))]
			b = append(b, []byte(v)...)
			if r.Intn(3) == 0 {
				b = append(b, 0x20)
			}
			if e < elems-1 {
				b = append(b, ',')
			}
		}
		b = append(b, '}')
		_ = depth
		if r.Intn(6) == 0 && len(b) > 2 {
			pos := r.Intn(len(b))
			b = append(b[:pos], append([]byte{badByte[r.Intn(len(badByte))]}, b[pos:]...)...)
		}
		got := validateJSONCharacters(b)
		want := referenceBad(b)
		// Only compare on documents that are well-formed JSON (scanner promises
		// no false positives there); invalid JSON may go either way.
		var tmp any
		wellFormed := json.Unmarshal(b, &tmp) == nil
		if wellFormed {
			if (got != nil) != want {
				t.Fatalf("mismatch on well-formed JSON:\n bytes=% x\n got=%v wantBad=%v", b, got, want)
			}
			// Stronger: every well-formed doc the reference flags must actually
			// be one json decodes with replacement (proves it is a real case).
		}
	}
	fmt.Println("differential fuzz done")
}

