func TestCLIAuditInvalidUTF8InSourceRejected(t *testing.T) {
	bin := auditBinary(t)
	work := t.TempDir()
	// 直接构造：source 字符串里夹一个 0xFF；note 合法。
	artifact := []byte(`{"name":"Vault","abi":"abi","bytecode":"0x1","source":"s` + "\xFF" + `c"}`)
