	if err != nil {
		t.Fatal(err)
	}
	if len(before) != 1 {
		t.Fatalf("setup expected 1 report, got %v", before)
	}
	existing := filepath.Join(store, before[0])
	existingBytes, err := os.ReadFile(existing)
	if err != nil {
		t.Fatal(err)
	}

