		token string
		want  string
	}{
		{"direct replacement char", `"含 � 字符"`, "含 � 字符"},
		{"literal backslash uD800", `"路径 \\uD800 文本"`, `路径 \uD800 文本`},
	} {
		t.Run(tc.name, func(t *testing.T) {
			input := writeInput(t, work, tc.name+".json", cliCharDoc(t, tc.token))
