1	// Package contractsentinel charvalidate: character-level legality checks for
2	// user-supplied audit submissions, performed before any JSON decoding.
3	//
4	// encoding/json silently rewrites two kinds of bad input into the replacement
5	// character U+FFFD instead of rejecting it:
6	//
7	//   - bytes that are not valid UTF-8, anywhere in the document;
8	//   - Unicode escapes (\uXXXX) inside JSON strings that do not form a legal
9	//     surrogate pair: a lone high surrogate, a lone low surrogate, or a high
10	//     surrogate followed by anything other than a low surrogate (a reversed
11	//     pair included).
12	//
13	// Left uncaught, the rewrite changes the evidence text of a 发现缺陷 record
14	// into replacement characters, and changes the very content that feeds the
15	// artifact hash when the bad text appears in the source. A successful report
16	// must never be built from rewritten content, so the whole submission is
17	// rejected at the character level first.
18	//
19	// Legal content stays legal: a directly written U+FFFD is an ordinary
20	// character, and the literal text "\uD800" (an escaped backslash followed by
21	// uD800) is ordinary text — neither is a surrogate problem.
22	package contractsentinel
23	
24	import (
25		"fmt"
26		"unicode/utf8"
27	)
28	
29	// charPos is one 1-based (line, column) position with an additional 0-based
30	// byte offset. Columns count runes, so a multi-byte character occupies one
31	// column. For a surrogate escape, surrogate records the escaped code point.
32	type charPos struct {
33		line      int
34		column    int
35		offset    int
36		surrogate rune
37	}
38	
39	// charError locates one character-legality problem.
40	type charError struct {
41		problem string // "invalid UTF-8 encoding" or "invalid Unicode escape in JSON string"
42		pos     charPos
43		detail  string
44	}
45	
46	func (e *charError) Error() string {
47		return fmt.Sprintf("%s at line %d, column %d (byte offset %d): %s",
48			e.problem, e.pos.line, e.pos.column, e.pos.offset, e.detail)
49	}
50	
51	// validateJSONCharacters scans data as JSON text and rejects the first
52	// character-legality violation: an illegal UTF-8 byte anywhere, or an
53	// unpaired / misordered surrogate escape within any JSON string (member names
54	// included — strings are strings, whether they carry a fixed field, a value,
55	// or nested extension data). It performs no JSON syntax validation: malformed
56	// JSON is left to the decoder that runs next, and a document that was valid
57	// JSON never produces a character error here.
58	func validateJSONCharacters(data []byte) error {
59		i, n := 0, len(data)
60		line, column := 1, 1
61		inString := false
62	
63		// Position of a high surrogate waiting for its low surrogate, so a lone
64		// high is reported where it was written rather than where pairing failed.
65		pending := charPos{}
66		hasPending := false
67	
68		for i < n {
69			c := data[i]
70	
71			// Non-ASCII bytes are validated as UTF-8 both inside and outside
72			// strings. A genuinely encoded U+FFFD decodes as U+FFFD over three
73			// bytes and is ordinary content; only an illegal encoding yields
74			// RuneError with size 1.
75			if c >= 0x80 {
76				r, size := utf8.DecodeRune(data[i:])
77				if r == utf8.RuneError && size == 1 {
78					return &charError{
79						problem: "invalid UTF-8 encoding",
80						pos:     charPos{line: line, column: column, offset: i},
81						detail:  fmt.Sprintf("illegal byte 0x%02X is not valid UTF-8", c),
82					}
83				}
84				// A literal rune is not a low surrogate, so a waiting high
85				// surrogate is already unpaired.
86				if inString && hasPending {
87					return loneHighError(pending)
88				}
89				i += size
90				column++
91				continue
92			}
93	
94			if !inString {
95				if c == '"' {
96					inString = true
97				}
98				i, line, column = advanceChar(c, i, line, column)
99				continue
100			}
101	
102			// Inside a JSON string.
103			switch c {
104			case '"':
105				if hasPending {
106					return loneHighError(pending)
107				}
108				inString = false
109				i, line, column = advanceChar(c, i, line, column)
110			case '\\':
111				if esc, pos, ok := surrogateEscape(data, i, line, column); ok {
112					switch {
113					case isHighSurrogate(esc):
114						if hasPending {
115							// The previous high escape was never completed by a low
116							// escape; another high escape is not its pair.
117							return loneHighError(pending)
118						}
119						pending, hasPending = pos, true
120					case isLowSurrogate(esc):
121						if !hasPending {
122							return &charError{
123								problem: "invalid Unicode escape in JSON string",
124								pos:     pos,
125								detail:  fmt.Sprintf("lone low surrogate \\u%04X has no preceding high surrogate \\uD800-\\uDBFF", esc),
126							}
127						}
128						hasPending = false
129					default:
130						// A non-surrogate escape cannot complete a waiting high.
131						if hasPending {
132							return loneHighError(pending)
133						}
134					}
135					i += 6
136					column += 6
137				} else {
138					// Any other escape (\\, \", \n, a malformed \u...): one token
139					// that is not a low surrogate. Consuming both bytes of "\\uD800"
140					// together keeps the backslash-u-D800 text literal instead of
141					// opening a surrogate escape. Malformed \u escapes are left for
142					// the JSON decoder after the already-unpaired high is reported.
143					if hasPending {
144						return loneHighError(pending)
145					}
146					if i+1 < n {
147						i += 2
148						column += 2
149					} else {
150						i++
151						column++
152					}
153				}
154			default:
155				// A literal byte is another JSON character, so a waiting high
156				// surrogate proves unpaired. Raw control characters are left to the
157				// decoder.
158				if hasPending {
159					return loneHighError(pending)
160				}
161				i, line, column = advanceChar(c, i, line, column)
162			}
163		}
164		if hasPending {
165			return loneHighError(pending)
166		}
167		return nil
168	}
169	
170	// advanceChar moves one ASCII byte, tracking line and column.
171	func advanceChar(c byte, i, line, column int) (int, int, int) {
